import { styled, Text, View } from '@tamagui/web';
import type { ReactElement } from 'react';

import type { CodeSnippetContract } from './CodeSnippet.contract';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebPreProps } from '../../types/WebElementProps';
import { Button } from '../Button';
import { Skeleton } from '../Skeleton';

export type CodeSnippetProps = WebPreProps<CodeSnippetContract> & {
	/** @deprecated Use `onPress`. */
	onClick?: () => void;
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const codeSnippetFrame = {
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: '$size.x60',
	display: 'flex',
	justifyContent: 'space-between',
	width: '100%',
	padding: '$space.x16',
	color: '$rcx-font-default',
	borderRadius: '$radius.medium',
	backgroundColor: '$rcx-surface-neutral',
} as const;

const codeSnippetCodeBox = {
	render: 'div',
	flexBasis: 'auto',
	wordWrap: 'inherit',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	marginInlineEnd: '$space.x8',
	whiteSpace: 'pre-line',
	wordBreak: 'break-all',
} as const;

const codeSnippetAction = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
} as const;

// end of generated

const CodeSnippetFrame = styled(View, { render: 'pre', ...codeSnippetFrame });

const CodeSnippetCodeBox = styled(Text, { ...codeSnippetCodeBox });

const CodeSnippetAction = styled(View, { render: 'div', ...codeSnippetAction });

/**
 * The `CodeSnippet` is used to show code or commands and make easier to copy them.
 *
 * The default button text is `Copy` but you can use the `buttonText` prop to handle translations in your project.
 *
 * Please check the `useClipBoard` hook in `fuselage-hooks` package, to handle the copy behaviour.
 */
const CodeSnippet = (props: CodeSnippetProps): ReactElement<CodeSnippetProps> => {
	const { children, onPress, onClick, buttonText = 'Copy', buttonDisabled = false, className } = props;
	const classes = prependClassName(className, 'rcx-box rcx-box--full rcx-code-snippet');

	if (!children) {
		return (
			<CodeSnippetFrame
				className={classes}
				render={<pre {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
			>
				<Skeleton width='100%' aria-hidden aria-busy />
			</CodeSnippetFrame>
		);
	}

	const handlePress = () => {
		onClick?.();
		onPress?.();
	};

	return (
		<CodeSnippetFrame
			className={classes}
			render={<pre {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
		>
			<CodeSnippetCodeBox className='rcx-box rcx-box--full rcx-code-snippet__codebox' render={<div role='code' />}>
				{children}
			</CodeSnippetCodeBox>
			{(onPress || onClick) && (
				<CodeSnippetAction className='rcx-box rcx-box--full'>
					<Button size='small' variant='primary' onClick={handlePress} disabled={buttonDisabled}>
						{buttonText}
					</Button>
				</CodeSnippetAction>
			)}
		</CodeSnippetFrame>
	);
};

export default CodeSnippet;
